package com.bookstore.bike.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User student; @ManyToOne(optional=false) private Bike bike; private Instant startAt,endAt,createdAt=Instant.now(); private BigDecimal rentalAmount,deposit,totalAmount; @Enumerated(EnumType.STRING) private Enums.BookingStatus status=Enums.BookingStatus.PENDING; @Enumerated(EnumType.STRING) private Enums.PaymentStatus paymentStatus=Enums.PaymentStatus.PENDING; private String pickupLocation,returnLocation;
 public Long getId(){return id;} public User getStudent(){return student;} public void setStudent(User v){student=v;} public Bike getBike(){return bike;} public void setBike(Bike v){bike=v;} public Instant getStartAt(){return startAt;} public void setStartAt(Instant v){startAt=v;} public Instant getEndAt(){return endAt;} public void setEndAt(Instant v){endAt=v;} public BigDecimal getRentalAmount(){return rentalAmount;} public void setRentalAmount(BigDecimal v){rentalAmount=v;} public BigDecimal getDeposit(){return deposit;} public void setDeposit(BigDecimal v){deposit=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public Enums.BookingStatus getStatus(){return status;} public void setStatus(Enums.BookingStatus v){status=v;} public Enums.PaymentStatus getPaymentStatus(){return paymentStatus;} public void setPaymentStatus(Enums.PaymentStatus v){paymentStatus=v;} public String getPickupLocation(){return pickupLocation;} public void setPickupLocation(String v){pickupLocation=v;} public String getReturnLocation(){return returnLocation;} public void setReturnLocation(String v){returnLocation=v;}}
